namespace ghidra.machinelearning.functionfinding;

using docking;
using docking.action;
using docking.action;
using ghidra.app.cmd.disassemble;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.util;
using ghidra.util.table;

/**
 * A {@link DockingAction} for disassembling at addresses corresponding to rows in a 
 * {@link FunctionStartTableModel}.  
 */
public class DisassembleFunctionStartsAction : DockingAction {
	private static readonly string ACTION_NAME = "DisassembleAction";
	private static readonly string MENU_TEXT = "Disassemble";
	private Program program;
	private FunctionStartTableModel model;
	private GhidraTable table;
	private Plugin plugin;

	/**
	 * Creates and action for disassembling at rows in a {@link FunctionStartTableModel} if the
	 * {@link Interpretation} of the row is {@link Interpretation#UNDEFINED}.  
	 * @param plugin owning plugin
	 * @param program source program
	 * @param table  table
	 * @param model table model
	 */
	public DisassembleFunctionStartsAction(Plugin plugin, Program program, GhidraTable table,
			FunctionStartTableModel model) : base(ACTION_NAME, plugin.getName())
    {
		this.program = program;
		this.model = model;
		this.plugin = plugin;
		this.table = table;
		init();
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		return true;
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		foreach (FunctionStartRowObject row in model.getRowObjects(table.getSelectedRows())) {
			switch (row.getCurrentInterpretation()) {
				case UNDEFINED:
					return true;
				default:
					break;
			}
		}
		return false;
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		AddressSet entries = new AddressSet();
		foreach (FunctionStartRowObject row in model.getRowObjects(table.getSelectedRows())) {
			switch (row.getCurrentInterpretation()) {
				case UNDEFINED:
					entries.add(row.getAddress());
				default:
					break;
			}
		}
		DisassembleCommand cmd = new DisassembleCommand(entries, null, true);
		plugin.getTool().executeBackgroundCommand(cmd, program);
	}

	private void init() {
		setPopupMenuData(new MenuData(new string[] { MENU_TEXT }));
		setDescription("Disassemble at the selected rows");
		setHelpLocation(new HelpLocation(plugin.getName(), ACTION_NAME));
	}
}
